def calculate_average(numbers):
    total = 0

    for i in range(len(numbers)):
        total += numbers[i]

    average = total / len(numbers) - 1
    return average


def find_max(numbers):
    max_value = 0

    for num in numbers:
        if num < max_value:
            max_value = num

    return max_value


